import{z as A,x as B,o as E,c as l,q as t,j as i,D as e,d as n,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"参数扫描的架构","description":"","frontmatter":{"title":"参数扫描的架构","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-param-sweep-arch.md","filePath":"quant/bf-param-sweep-arch.md","lastUpdated":1791063341000}'),p={name:"quant/bf-param-sweep-arch.md"};function d(h,a,f,c,m,u){const r=B("Mermaid");return E(),l("div",null,[a[2]||(a[2]=t('<h1 id="参数扫描的架构" tabindex="-1">参数扫描的架构 <a class="header-anchor" href="#参数扫描的架构" aria-label="Permalink to &quot;参数扫描的架构&quot;">​</a></h1><div class="epigraph"><p>每个被看过的参数格子都是一次试验；扫描架构的职责是让这个 $N$ 数得出来、存得下来、赖不掉。</p><footer>—— 据 Bailey, Borwein, López de Prado and Zhu, The Probability of Backtest Overfitting 及 Notices of the AMS, 2014 对多重检验的论述；对照 White, Econometrica, 2000 整理</footer></div><p><a href="/quant/bf-multiasset">上一课</a>把引擎撑到多资产，剩下的工程问题是规模：一个策略族乘参数网格乘多市场，运行与评估都得有架构。本课把扫描写成框架的一等公民：配置对象、试验身份、结果存储与试验计数。筛选层用向量化的算力（见<a href="/quant/bf-vectorized-vs-event">向量化与事件驱动的取舍</a>），本课写的是那一层之上的组织学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>笔记本里的扫描死于四件事。结果只活在 notebook 里，三天后连作者也不知道胜者参数是哪次运行、哪份数据；只记录胜者，参数面上的邻域稳定性与鲁棒性再也问不出来；报错与中断的运行被顺手丢弃，配置层面重演一遍幸存者偏差；最要命的是 \\(N\\) 失忆——看过两百个格子，报告里写「我们试了三个想法」，<a href="/quant/backtest-overfitting">过拟合次数与试错</a>的调整从此无从谈起。缺的不是更快 sweeping，而是一套让每一次「看过结果」都留痕的架构。</p><h3 id="配置、身份与结果库" tabindex="-1">配置、身份与结果库 <a class="header-anchor" href="#配置、身份与结果库" aria-label="Permalink to &quot;配置、身份与结果库&quot;">​</a></h3><p>扫描的三件套。<strong>配置对象</strong>是声明式的：策略版本、宇宙、参数网格、数据版本、成本情景、种子，一个字典说尽。<strong>试验身份</strong>是配置、代码哈希与数据版本的联合哈希——数据版本来自平台（<a href="/quant/de-tsdb-selection">时序数据库的选型</a>的版本化），没有它，供应商一次刷新就让历史结论不可复现。<strong>结果库</strong>按身份存每一次运行的完整产物：权益路径、成交日志、指标、报错。失败也是结果；只存胜者的结果库，在配置层面先行一遍<a href="/quant/survivorship-bias">幸存者偏差</a>。</p>',7)),(E(),i(s,null,{default:e(()=>[o(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E5%A3%B0%E6%98%8E%E5%BC%8F%E9%85%8D%E7%BD%AE%20%E7%BD%91%E6%A0%BC%E4%B8%8E%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20ID%5B%22%E8%AF%95%E9%AA%8C%E8%BA%AB%E4%BB%BD%20%E9%85%8D%E7%BD%AE%E4%B9%98%E4%BB%A3%E7%A0%81%E4%B9%98%E6%95%B0%E6%8D%AE%22%5D%0A%20%20ID%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%20%E5%90%91%E9%87%8F%E5%8C%96%E5%B1%82%E9%80%90%E6%A0%BC%E8%BF%90%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20ST%5B%22%E7%BB%93%E6%9E%9C%E5%BA%93%20%E6%88%90%E8%B4%A5%E5%85%A8%E5%AD%98%22%5D%0A%20%20ST%20--%3E%20EV%5B%22%E8%AF%84%E4%BC%B0%E5%B1%82%20%E5%88%86%E5%B8%83%E4%B8%8E%E9%80%89%E6%8B%A9%22%5D%0A%20%20EV%20--%3E%20N%5B%22%E8%AF%95%E9%AA%8C%E8%AE%A1%E6%95%B0%E8%BF%9B%20DSR%20%E4%B8%8E%20PBO%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>评估层读的是全网格，不是冠军。报告的最小集合：参数面热图与邻域稳定性（冠军参数的邻居是否同样好，还是孤峰）；样本内外散点与<a href="/quant/cpcv">组合过拟合 CPCV</a> 的路径分布；以有效试验数填入 <a href="/quant/deflated-sharpe">Deflated Sharpe</a>。有效数是关键修正：网格里的格子高度相关，\\(5\\times5\\) 的格子簇可能只等于三五个独立假设；名义格子数填进多重检验调整会高估显著性，应按参数邻域聚类计数，与<a href="/quant/multitest-discipline-cap">多重检验纪律的现场用法</a>一致。搜索策略上，网格与随机采样适合铺面，贝叶斯优化省算力但每一步查询都自适应于已看结果——查询次数同样计入 \\(N\\)，不能因为「智能」就免票。</p><p><span class="marginnote">把报错的运行也写进结果库并标出原因：某格因数据缺口失败，与某格因策略失效亏损，是两种信息。静默丢掉前者，参数面上会出现一片看似「未评估」实为「不可评估」的空洞，后续的人会把它当成空地重新踩一遍。</span></p><p><span class="marginnote">给个数字：\\(5\\times5\\) 的参数网格名义上是 \\(25\\) 次试验，但相邻格子高度相关——若按邻域聚类只折出 \\(4\\) 个独立假设，填进 Deflated Sharpe 的有效 \\(N\\) 就取 \\(4\\) 而不是 \\(25\\)。取 \\(25\\) 会把显著性门槛放得过宽，让平庸的夏普也显得能过关。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扫描架构真正的机制是把「选择」从「运行」中剥离。执行器是无视角的：给它身份与配置，它产出结果，不知道谁是冠军；选择只发生在评估层，而评估层看到的永远是分布。这样分离之后，任何后续问题——鲁棒性面、参数敏感性、换一个成本情景重读——都不需要重跑，只需要重新读库。试验计数也因此有了账本：结果库里的每一行都是一次看过，\\(N\\) 不再依赖作者的记忆。预注册的假设与扫描的关系同样清晰：扫描生成假设，预注册（<a href="/quant/hypothesis-preregistration">假设与预注册</a>）冻结下一个样本外的检验，两者的分界就是结果库的某一次读取。</p>',6)),(E(),i(s,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20EX%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%20%E6%97%A0%E8%A7%86%E8%A7%92%20%E9%80%90%E6%A0%BC%E4%BA%A7%E5%87%BA%22%5D%20--%3E%20RL%5B%22%E7%BB%93%E6%9E%9C%E5%BA%93%20%E6%88%90%E8%B4%A5%E5%85%A8%E5%AD%98%22%5D%0A%20%20RL%20--%3E%20Q1%5B%22%E8%AF%BB%E6%B3%95%E4%B8%80%20%E5%8F%82%E6%95%B0%E9%9D%A2%E7%83%AD%E5%9B%BE%22%5D%0A%20%20RL%20--%3E%20Q2%5B%22%E8%AF%BB%E6%B3%95%E4%BA%8C%20%E6%8D%A2%E6%88%90%E6%9C%AC%E6%83%85%E6%99%AF%E9%87%8D%E8%AF%BB%22%5D%0A%20%20RL%20--%3E%20Q3%5B%22%E8%AF%BB%E6%B3%95%E4%B8%89%20%E8%AE%A1%E6%9C%89%E6%95%88%E8%AF%95%E9%AA%8C%E6%95%B0%22%5D%0A%20%20Q1%20--%3E%20AN%5B%22%E9%87%8D%E6%96%B0%E8%AF%BB%E5%BA%93%E5%8D%B3%E5%BE%97%E7%AD%94%E6%A1%88%20%E4%B8%8D%E5%BF%85%E9%87%8D%E8%B7%91%22%5D%0A%20%20Q2%20--%3E%20AN%0A%20%20Q3%20--%3E%20AN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">「选择与运行剥离」可以想象成体检中心与医生：体检中心（执行器）只管按单子抽血出报告，不知道也不关心你哪里不舒服；诊断（评估层）是医生拿着全部指标做的，想换个角度分析就重读报告，不必重新抽血——回测里「重新抽血」就是重跑扫描，又慢又多花一次 \\(N\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>扫描不替代时序协议：CPCV 与<a href="/quant/walk-forward">样本外与滚动检验</a>回答的是路径与漂移，参数面回答的是邻域，三层互补。也不要在看过事件层结果之后回头重扫向量层——那是用新一次试验去解释旧试验，\\(N\\) 翻倍而报告不变，是最常见的隐性膨胀。算力不是约束，纪律才是：结果库会诱惑「反正便宜再扫一轮」，每一轮都在花同一个 \\(N\\) 的额度。</p><p><span class="marginnote">常见误区：把结果库当「备份」，存不存都行。其实它是账本——\\(N\\) 的每一个计数都以库中的一行为凭；没有账本，「我们只试了三个想法」就无从审计，多重检验调整也就退化成自我申报的荣誉制度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描三件套：声明式配置、试验身份（配置乘代码乘数据版本）、成败全存的结果库。</li><li>评估层读分布不读冠军：参数面、邻域稳定性、CPCV 路径、按有效数填 DSR。</li><li>网格格子相关，名义试验数高估独立性；按邻域聚类计数，贝叶斯查询同样计票。</li><li>选择与运行剥离；预注册与扫描的分界是结果库的某一次读取。</li><li>出处：Bailey, Borwein, López de Prado and Zhu, <em>Journal of Computational Finance</em>, 2017 与 <em>Notices of the AMS</em>, 2014；White, <em>Econometrica</em>, 2000；站内<a href="/quant/cpcv">组合过拟合 CPCV</a>、<a href="/quant/backtest-overfitting">过拟合次数与试错</a>各课。</li></ul>',6))])}const C=A(p,[["render",d]]);export{_ as __pageData,C as default};
